-- Lote único aprobado. Instalación de infraestructura: NO importa compras ni cortes.
-- Manifiesto SHA256: 46848e7ef677543502040b0cb37c8021549dd41f4e4f417e6b7a883fe09c4efc
-- 140004 SHA256: 24a78e37867518043cc542bc0519360aff979e6002f105ec5e6c2cb4ea960011
begin;
create table public.control_lote_compras_historicas (
 clave text primary key check(clave='COMPRAS_SHEETS_60_V1'),
 manifiesto_sha256 text not null check(manifiesto_sha256='46848e7ef677543502040b0cb37c8021549dd41f4e4f417e6b7a883fe09c4efc'),
 infraestructura jsonb not null,
 baseline_instalacion jsonb not null,
 actor_id uuid references auth.users(id) on delete restrict,
 antes jsonb,
 despues jsonb,
 aplicado_at timestamptz,
 check ((actor_id is null and antes is null and despues is null and aplicado_at is null)
  or (actor_id is not null and antes is not null and despues is not null and aplicado_at is not null))
);
alter table public.control_lote_compras_historicas owner to postgres;
alter table public.control_lote_compras_historicas enable row level security;
revoke all on public.control_lote_compras_historicas from public,anon,authenticated,service_role;

-- Catálogo estable, sin OID ni timestamps. Cubre cuerpos/ACL de RPC y helpers,
-- columnas, CHECK/FK/UNIQUE, índices, triggers activos, RLS y permisos de tablas.
create function public.catalogo_lote_compras_historicas_interno() returns jsonb
language sql volatile security definer set search_path='' as $catalogo$
 select jsonb_build_object(
 'funciones',(select jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,p.prosrc,p.prosecdef,
  pg_get_userbyid(p.proowner),p.proconfig,p.provolatile,p.proacl::text) order by p.oid::regprocedure::text)
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
   and (p.proname like '%compra%' or p.proname like '%tarjeta%' or p.proname like '%historica%' or p.proname='es_admin_hugella')),
 'tablas',(select jsonb_object_agg(c.relname,jsonb_build_object(
  'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text,
  'columnas',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attgenerated,pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',(select jsonb_agg(jsonb_build_array(x.conname,x.contype,x.convalidated,pg_get_constraintdef(x.oid)) order by x.conname) from pg_constraint x where x.conrelid=c.oid),
  'indices',(select jsonb_agg(jsonb_build_array(i.indisunique,i.indisvalid,pg_get_indexdef(i.indexrelid)) order by pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid=c.oid),
  'triggers',(select jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) order by t.tgname) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
  'policies',(select jsonb_agg(to_jsonb(p)-array['oid','polrelid'] order by p.polname) from pg_policy p where p.polrelid=c.oid)))
  from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in
 ('compras_gastos','items_compras_gastos','operaciones_compras_gastos','operaciones_financieras_compras',
 'financiaciones_compras','tramos_pago_compras','obligaciones_tarjetas','inicios_tramos_tarjeta',
 'tarjetas_credito','periodos_tarjetas','proveedores','pagos_resumenes_tarjetas','aplicaciones_pagos_obligaciones',
 'anulaciones_compras_gastos','cortes_historicos_obligaciones_tarjeta','evidencias_financiacion_historica_compras','control_lote_compras_historicas')));
$catalogo$;
