create function public.snapshot_lote_compras_historicas_interno() returns jsonb language sql volatile security definer set search_path='' as $snapshot$
 SELECT jsonb_build_object(
'anulaciones_compras_gastos',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.anulaciones_compras_gastos x),
'aplicaciones_pagos_obligaciones',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.aplicaciones_pagos_obligaciones x),
'compras_gastos',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.compras_gastos x),
'cortes_historicos_obligaciones_tarjeta',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.cortes_historicos_obligaciones_tarjeta x),
'evidencias_financiacion_historica_compras',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.evidencias_financiacion_historica_compras x),
'financiaciones_compras',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.financiaciones_compras x),
'inicios_tramos_tarjeta',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.inicios_tramos_tarjeta x),
'items_compras_gastos',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.items_compras_gastos x),
'obligaciones_tarjetas',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.obligaciones_tarjetas x),
'operaciones_compras_gastos',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.operaciones_compras_gastos x),
'operaciones_financieras_compras',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.operaciones_financieras_compras x),
'pagos_resumenes_tarjetas',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.pagos_resumenes_tarjetas x),
'periodos_tarjetas',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.periodos_tarjetas x),
'proveedores',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.proveedores x),
'tarjetas_credito',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.tarjetas_credito x),
'tramos_pago_compras',(SELECT coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]'::jsonb) FROM public.tramos_pago_compras x));
$snapshot$;

create function public.validar_referencias_lote_compras_historicas_interno() returns void
language plpgsql volatile security definer set search_path='' as $refs$
declare r jsonb; refs jsonb:=public.referencias_lote_compras_historicas_interno();
begin
 if (select count(*) from public.proveedores)<>10 or (select count(*) from public.tarjetas_credito)<>2
  or (select count(*) from public.periodos_tarjetas)<>6 then
  raise exception 'C PARCIAL_O_INCONSISTENTE: cantidad de referencias incompatible'; end if;
 for r in select value from jsonb_array_elements(refs->'proveedores') loop
  if not exists(select 1 from public.proveedores p where p.id=(r->>'id')::uuid and p.nombre=r->>'nombre' and p.activo) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: proveedor %',r->>'nombre'; end if;
 end loop;
 for r in select value from jsonb_array_elements(refs->'tarjetas') loop
  if not exists(select 1 from public.tarjetas_credito t where t.id=(r->>'id')::uuid
   and t.nombre=r->>'nombre' and t.entidad=r->>'entidad' and t.activo) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: tarjeta %',r->>'nombre'; end if;
 end loop;
 for r in select value from jsonb_array_elements(refs->'periodos') loop
  if not exists(select 1 from public.periodos_tarjetas p where p.id=(r->>'id')::uuid
   and p.tarjeta_id=(r->>'tarjeta_id')::uuid and p.orden=(r->>'orden')::integer
   and p.fecha_cierre=(r->>'fecha_cierre')::date and p.fecha_vencimiento=(r->>'fecha_vencimiento')::date) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: período %',r->>'id'; end if;
 end loop;
end;
$refs$;

create function public.validar_baseline_lote_compras_historicas_interno() returns void
language plpgsql volatile security definer set search_path='' as $base$
begin
 perform public.validar_referencias_lote_compras_historicas_interno();
 -- Baseline REAL comunicado y verificado manualmente por el administrador.
 -- EXCEPT compara NULL y timestamps tipados sin depender del formato de zona.
