  ('ab8e8956-ea0c-4b30-a7b3-994be00a6a21'::uuid,2,114499.67::numeric,null::uuid),
  ('fa4ce36c-1fb8-4299-bc34-f0e68d6ffdd8'::uuid,3,114499.66::numeric,null::uuid)
 ) esperado except select id,numero_cuota,importe,periodo_id from public.obligaciones_tarjetas
  where compra_id='7171c5cb-90dc-4a41-a470-29b207bc2895') then
