  or exists(select 1 from public.obligaciones_tarjetas o where
   o.compra_id<>'7171c5cb-90dc-4a41-a470-29b207bc2895' or o.tramo_id<>'362fba80-fa95-49ff-8514-22dbf1627c2d'
   or o.tarjeta_id<>'6087c186-6e63-4469-9b4d-99f0873caf5e' or o.cantidad_cuotas<>3
   or o.numero_cuota not between 1 and 3
   or o.importe<>case when o.numero_cuota=3 then 114499.66 else 114499.67 end
   or o.periodo_id is distinct from case when o.numero_cuota=1 then '5d5a4689-416e-451b-add1-ec71fd3eea36'::uuid else null::uuid end)
  or not exists(select 1 from public.obligaciones_tarjetas where id='545c1742-003a-451c-9e55-748d1cc93dcb' and numero_cuota=1) then
  raise exception 'C PARCIAL_O_INCONSISTENTE: impresora'; end if;
