-- Compara cada fila con el manifiesto del servidor, no sólo sumas agregadas.
create function public.validar_resultado_lote_compras_historicas_interno(p_con_cortes boolean,p_actor uuid) returns void
language plpgsql volatile security definer set search_path='' as $audit$
declare e jsonb; r jsonb; c public.compras_gastos%rowtype; t public.tramos_pago_compras%rowtype;
 o public.obligaciones_tarjetas%rowtype; ev jsonb; n integer; expected numeric; pid uuid; cut jsonb;
 request jsonb; expected_tramos jsonb; op uuid; corte_count integer:=0;
begin
 perform public.validar_referencias_lote_compras_historicas_interno();
 if (select count(*) from public.compras_gastos)<>62
  or (select count(*) from public.compras_gastos where fuente='GOOGLE_SHEETS_COMPRAS')<>60
  or exists(select 1 from public.compras_gastos where id_origen='HG-0002')
  or (select count(*) from public.obligaciones_tarjetas)<>283
  or exists(select 1 from public.pagos_resumenes_tarjetas)
  or exists(select 1 from public.aplicaciones_pagos_obligaciones)
  or (select count(*) from public.evidencias_financiacion_historica_compras)<>58
  or (select sum(cuotas_fuente) from public.evidencias_financiacion_historica_compras)<>281
  or (select sum(pendientes_historicas) from public.evidencias_financiacion_historica_compras)<>227
  or (select count(*) from public.cortes_historicos_obligaciones_tarjeta)<>(case when p_con_cortes then 54 else 0 end)
  or (select count(*) from public.compras_gastos where fuente='GOOGLE_SHEETS_COMPRAS' and tipo='MERCADERIA')<>57
  or (select count(*) from public.compras_gastos where fuente='GOOGLE_SHEETS_COMPRAS' and tipo='GASTO')<>3
  or (select sum(i.total) from public.items_compras_gastos i join public.compras_gastos cg on cg.id=i.compra_gasto_id where cg.fuente='GOOGLE_SHEETS_COMPRAS') is distinct from 17186976.43::numeric then
  raise exception 'C PARCIAL_O_INCONSISTENTE: controles globales'; end if;
 for e in select value from jsonb_array_elements(public.datos_lote_compras_historicas_interno()) loop
  r:=e->'row'; ev:=nullif(e->'evidencia','null'::jsonb); op:=(e->>'op')::uuid;
  select * into strict c from public.compras_gastos where fuente='GOOGLE_SHEETS_COMPRAS' and id_origen=r->>'id_origen';
  if c.tipo is distinct from r->>'tipo' or c.proveedor_id is distinct from (e->>'proveedor_id')::uuid
   or c.fecha is distinct from (r->>'fecha')::date or c.moneda is distinct from r->>'moneda'
   or c.actor_id is distinct from p_actor or c.comprobante is not null or c.observaciones is not null
   or (select count(*) from public.items_compras_gastos where compra_gasto_id=c.id)<>1
   or not exists(select 1 from public.items_compras_gastos i where i.compra_gasto_id=c.id and i.posicion=1
    and i.descripcion=btrim(r->>'descripcion') and i.modalidad='TOTAL_HISTORICO' and i.cantidad is null and i.costo_unitario is null
    and i.importe_historico=(r->>'total_historico')::numeric and i.total=(r->>'total_historico')::numeric)
   or exists(select 1 from public.anulaciones_compras_gastos where compra_gasto_id=c.id) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: compra %',c.id_origen; end if;
  request:=jsonb_build_object('fuente','GOOGLE_SHEETS_COMPRAS','id_origen',c.id_origen,'tipo',r->>'tipo',
   'proveedor_id',e->>'proveedor_id','fecha',r->>'fecha','moneda',r->>'moneda','comprobante',null,'observaciones',null,
   'descripcion',btrim(r->>'descripcion'),'total',(r->>'total_historico')::numeric);
  expected_tramos:=public.canonicalizar_tramos_compra_interno(e->'tramos');
  if not exists(select 1 from public.operaciones_compras_gastos x where x.operacion_id=md5('hugella:compra-historica:compra:v1:'||op::text)::uuid
    and x.compra_gasto_id=c.id and x.actor_id=p_actor and x.solicitud=request)
   or not exists(select 1 from public.operaciones_financieras_compras x where x.operacion_id=op and x.actor_id=p_actor
    and x.accion='IMPORTACION_COMPRA_HISTORICA' and x.solicitud=jsonb_build_object('compra',request,'tramos',expected_tramos,'evidencia_historica',ev)
    and x.resultado->>'compra_id'=c.id::text) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: operación %',c.id_origen; end if;
  if ev is not null then
   if (select to_jsonb(x)-array['compra_id','operacion_id','actor_id','created_at'] from public.evidencias_financiacion_historica_compras x where x.compra_id=c.id) is distinct from ev
    or not exists(select 1 from public.evidencias_financiacion_historica_compras where compra_id=c.id and actor_id=p_actor and operacion_id=op) then
    raise exception 'C PARCIAL_O_INCONSISTENTE: evidencia %',c.id_origen; end if;
  elsif exists(select 1 from public.evidencias_financiacion_historica_compras where compra_id=c.id) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: evidencia débito'; end if;
  if c.id_origen='HG-0043' then
   if exists(select 1 from public.financiaciones_compras where compra_id=c.id)
    or exists(select 1 from public.tramos_pago_compras where compra_id=c.id)
    or exists(select 1 from public.obligaciones_tarjetas where compra_id=c.id) then
    raise exception 'C PARCIAL_O_INCONSISTENTE: documental'; end if;
   continue;
  end if;
  if (select count(*) from public.tramos_pago_compras where compra_id=c.id)<>1
   or not exists(select 1 from public.financiaciones_compras where compra_id=c.id and estado='CONFIRMADA' and actor_id=p_actor) then
   raise exception 'C PARCIAL_O_INCONSISTENTE: financiación %',c.id_origen; end if;
  select * into strict t from public.tramos_pago_compras where compra_id=c.id;
  if t.posicion<>1 or t.importe<>(r->>'total_historico')::numeric or t.medio<>r->>'medio' then
   raise exception 'C PARCIAL_O_INCONSISTENTE: tramo %',c.id_origen; end if;
  if ev is null then
   if t.fecha_pago is distinct from c.fecha or t.tarjeta_id is not null or t.cantidad_cuotas is not null
    or t.estrategia_distribucion<>'NORMAL' or t.valor_cuota_historico is not null
    or exists(select 1 from public.obligaciones_tarjetas where compra_id=c.id) then
    raise exception 'C PARCIAL_O_INCONSISTENTE: débito %',c.id_origen; end if;
   continue;
  end if;
  if t.estrategia_distribucion<>'HISTORICA_SHEETS' or t.valor_cuota_historico is distinct from (ev->>'valor_cuota_historico')::numeric
   or t.tarjeta_id is distinct from (ev->>'tarjeta_id')::uuid or t.cantidad_cuotas is distinct from (r->>'cuotas')::integer
   or t.fecha_pago is not null or not exists(select 1 from public.inicios_tramos_tarjeta where tramo_id=t.id and primer_periodo_id=(ev->>'periodo_inicial_id')::uuid and actor_id=p_actor)
   or (select count(*) from public.obligaciones_tarjetas where compra_id=c.id)<>(r->>'cuotas')::integer then
   raise exception 'C PARCIAL_O_INCONSISTENTE: cuotas %',c.id_origen; end if;
  for n in 1..(r->>'cuotas')::integer loop
   select * into strict o from public.obligaciones_tarjetas where compra_id=c.id and numero_cuota=n;
   expected:=case when n=(r->>'cuotas')::integer then (r->>'total_historico')::numeric-(r->>'valor_cuota_historico')::numeric*(n-1) else (r->>'valor_cuota_historico')::numeric end;
   select p.id into pid from public.periodos_tarjetas p join public.periodos_tarjetas primero on primero.id=(ev->>'periodo_inicial_id')::uuid
    where p.tarjeta_id=t.tarjeta_id and p.orden=primero.orden+n-1;
   if o.tramo_id<>t.id or o.tarjeta_id<>t.tarjeta_id or o.cantidad_cuotas<>t.cantidad_cuotas
    or o.importe<>expected or o.periodo_id is distinct from pid then
    raise exception 'C PARCIAL_O_INCONSISTENTE: obligación % cuota %',c.id_origen,n; end if;
   if p_con_cortes and n<=(r->>'pagadas_historicas')::integer then
    select value into strict cut from jsonb_array_elements(e->'cortes') where (value->>'numero')::integer=n;
    if not exists(select 1 from public.cortes_historicos_obligaciones_tarjeta ch where ch.obligacion_id=o.id
     and ch.operacion_id=(cut->>'operacion_id')::uuid and ch.fuente='GOOGLE_SHEETS_COMPRAS'
     and ch.referencia=c.id_origen||' cuota '||n||' / fuente GOOGLE_SHEETS_COMPRAS'
     and ch.fecha_corte='2026-10-14' and ch.importe=expected and ch.actor_id=p_actor and o.periodo_id is not null)
     or not exists(select 1 from public.operaciones_financieras_compras x where x.operacion_id=(cut->>'operacion_id')::uuid
      and x.actor_id=p_actor and x.accion='CORTE_HISTORICO' and x.solicitud=jsonb_build_object('obligacion_id',o.id,'fuente','GOOGLE_SHEETS_COMPRAS',
       'referencia',c.id_origen||' cuota '||n||' / fuente GOOGLE_SHEETS_COMPRAS','fecha_corte','2026-10-14','importe',expected)) then
     raise exception 'C PARCIAL_O_INCONSISTENTE: corte % cuota %',c.id_origen,n; end if;
    corte_count:=corte_count+1;
   elsif exists(select 1 from public.cortes_historicos_obligaciones_tarjeta where obligacion_id=o.id) then
    raise exception 'C PARCIAL_O_INCONSISTENTE: corte adicional'; end if;
  end loop;
 end loop;
 if (select count(*) from public.obligaciones_tarjetas ob join public.compras_gastos cg on cg.id=ob.compra_id where cg.fuente='GOOGLE_SHEETS_COMPRAS' and ob.periodo_id is not null)<>104
  or (select count(*) from public.obligaciones_tarjetas ob join public.compras_gastos cg on cg.id=ob.compra_id where cg.fuente='GOOGLE_SHEETS_COMPRAS' and ob.periodo_id is null)<>176 then
  raise exception 'C PARCIAL_O_INCONSISTENTE: asignación de períodos'; end if;
 if p_con_cortes and (corte_count<>54 or
  (select sum(ob.importe)-coalesce(sum(ch.importe),0) from public.obligaciones_tarjetas ob join public.compras_gastos cg on cg.id=ob.compra_id
   left join public.cortes_historicos_obligaciones_tarjeta ch on ch.obligacion_id=ob.id where cg.fuente='GOOGLE_SHEETS_COMPRAS') is distinct from 14259630.21::numeric) then
  raise exception 'C PARCIAL_O_INCONSISTENTE: saldo/cortes'; end if;
end;
$audit$;

create function public.proteger_control_lote_compras_historicas_interno() returns trigger
language plpgsql security definer set search_path='' as $guard$
begin
 if tg_op<>'UPDATE' then raise exception 'Control de lote inmutable'; end if;
 if old.actor_id is not null or new.clave is distinct from old.clave
  or new.manifiesto_sha256 is distinct from old.manifiesto_sha256 or new.infraestructura is distinct from old.infraestructura
  or new.baseline_instalacion is distinct from old.baseline_instalacion
  or new.actor_id is distinct from auth.uid() or new.actor_id is null
  or public.es_admin_hugella() is not true or new.antes is null or new.despues is null or new.aplicado_at is null then
  raise exception 'Control de lote inmutable'; end if;
 return new;
end;
$guard$;
create trigger control_lote_inmutable before update or delete on public.control_lote_compras_historicas
for each row execute function public.proteger_control_lote_compras_historicas_interno();
create trigger control_lote_no_truncate before truncate on public.control_lote_compras_historicas
for each statement execute function public.proteger_control_lote_compras_historicas_interno();

-- Sin parámetros: ni payload, ni actor, ni JWT suministrados por el cliente.
-- Las llamadas anidadas conservan auth.uid(): SECURITY DEFINER cambia permisos,
-- nunca la identidad autenticada de la solicitud. No hay COMMIT intermedio.
create function public.importar_lote_compras_historicas_admin() returns jsonb
language plpgsql volatile security definer set search_path='' as $rpc$
declare actor uuid:=auth.uid(); ctl public.control_lote_compras_historicas%rowtype;
 e jsonb; r jsonb; cut jsonb; res jsonb; o public.obligaciones_tarjetas%rowtype;
 keys text[]:=array[]::text[]; op uuid; k bigint; before_state jsonb; after_state jsonb; v record; delta integer;
begin
 if actor is null or public.es_admin_hugella() is not true then
  raise exception 'No autorizado' using errcode='42501'; end if;
 if current_setting('server_version_num')::integer<170000 then raise exception 'Se requiere PostgreSQL 17'; end if;
 if current_setting('transaction_isolation')<>'read committed' then
  raise exception 'El lote requiere READ COMMITTED' using errcode='25000'; end if;
 -- Serializa el lote completo, incluso el reconocimiento de COMMIT incierto.
 perform pg_advisory_xact_lock(hashtextextended('hugella:lote:COMPRAS_SHEETS_60_V1',0));
 for e in select value from jsonb_array_elements(public.datos_lote_compras_historicas_interno()) loop
  op:=(e->>'op')::uuid;
  keys:=keys||array['hugella:historico:GOOGLE_SHEETS_COMPRAS:'||(e->'row'->>'id_origen'),
   'hugella:finanzas:operacion:'||op::text,
   'hugella:finanzas:operacion:'||md5('hugella:compra-historica:financiacion:v1:'||op::text)::uuid::text,
   'hugella:compra:operacion:'||md5('hugella:compra-historica:compra:v1:'||op::text)::uuid::text];
  for cut in select value from jsonb_array_elements(e->'cortes') loop
   keys:=array_append(keys,'hugella:finanzas:operacion:'||(cut->>'operacion_id'));
  end loop;
 end loop;
 if cardinality(keys)<>294 then raise exception 'Identidades del lote incompatibles'; end if;
 for k in select distinct hashtextextended(x,0) from unnest(keys) x order by 1 loop
  perform pg_advisory_xact_lock(k);
 end loop;
 perform pg_advisory_xact_lock(hashtextextended('hugella:finanzas:escritura',0));
 -- Bloquea también escrituras ajenas a las RPC financieras (p.ej. proveedores).
 -- Orden fijo, después de identidades y lock financiero; nunca desactiva defensas.
 lock table public.anulaciones_compras_gastos,public.aplicaciones_pagos_obligaciones,public.compras_gastos,
 public.control_lote_compras_historicas,public.cortes_historicos_obligaciones_tarjeta,
 public.evidencias_financiacion_historica_compras,public.financiaciones_compras,public.inicios_tramos_tarjeta,
 public.items_compras_gastos,public.obligaciones_tarjetas,public.operaciones_compras_gastos,
 public.operaciones_financieras_compras,public.pagos_resumenes_tarjetas,public.periodos_tarjetas,
 public.proveedores,public.tarjetas_credito,public.tramos_pago_compras in share row exclusive mode;
 select * into strict ctl from public.control_lote_compras_historicas where clave='COMPRAS_SHEETS_60_V1' for update;
 if ctl.infraestructura is distinct from public.catalogo_lote_compras_historicas_interno() then
  raise exception 'C PARCIAL_O_INCONSISTENTE: infraestructura/ACL alterada'; end if;
 before_state:=public.snapshot_lote_compras_historicas_interno();
 if ctl.actor_id is not null then
  if before_state is distinct from ctl.despues then
   raise exception 'C PARCIAL_O_INCONSISTENTE: lote aplicado cambió; revisión manual'; end if;
  perform public.validar_resultado_lote_compras_historicas_interno(true,ctl.actor_id);
  return jsonb_build_object('estado_lote','YA_APLICADO_CORRECTAMENTE','compras_historicas',60,
   'obligaciones_monetarias',280,'cortes_historicos',54,'saldo_pendiente',14259630.21);
 end if;
 -- Sin comprobante completo nunca se adopta/repara un lote preexistente.
 perform public.validar_baseline_lote_compras_historicas_interno();
 if before_state is distinct from ctl.baseline_instalacion then
  raise exception 'C PARCIAL_O_INCONSISTENTE: baseline cambió desde instalación'; end if;
 for e in select value from jsonb_array_elements(public.datos_lote_compras_historicas_interno()) loop
  r:=e->'row';
  res:=public.importar_compra_historica_admin((e->>'op')::uuid,r->>'id_origen',r->>'tipo',
   (e->>'proveedor_id')::uuid,(r->>'fecha')::date,r->>'moneda',null,null,r->>'descripcion',
   (r->>'total_historico')::numeric,e->'tramos',nullif(e->'evidencia','null'::jsonb));
  if res->>'id_origen' is distinct from r->>'id_origen' then raise exception 'Respuesta de compra incompatible'; end if;
 end loop;
 -- Fuerza todos los validadores originales ANTES de registrar el primer corte.
 set constraints all immediate;
 set constraints all deferred;
 perform public.validar_resultado_lote_compras_historicas_interno(false,actor);
 for e in select value from jsonb_array_elements(public.datos_lote_compras_historicas_interno()) loop
  r:=e->'row';
  for cut in select value from jsonb_array_elements(e->'cortes') order by (value->>'numero')::integer loop
   select ob.* into strict o from public.obligaciones_tarjetas ob join public.compras_gastos c on c.id=ob.compra_id
    where c.fuente='GOOGLE_SHEETS_COMPRAS' and c.id_origen=r->>'id_origen' and ob.numero_cuota=(cut->>'numero')::integer;
   if o.periodo_id is null or o.importe is distinct from (r->>'valor_cuota_historico')::numeric
    or exists(select 1 from public.aplicaciones_pagos_obligaciones where obligacion_id=o.id) then
    raise exception 'Corte histórico incompatible: % cuota %',r->>'id_origen',o.numero_cuota; end if;
   perform public.registrar_corte_historico_obligacion_admin((cut->>'operacion_id')::uuid,o.id,
    (r->>'id_origen')||' cuota '||o.numero_cuota||' / fuente GOOGLE_SHEETS_COMPRAS','2026-10-14',o.importe);
  end loop;
 end loop;
 set constraints all immediate;
 perform public.validar_resultado_lote_compras_historicas_interno(true,actor);
 after_state:=public.snapshot_lote_compras_historicas_interno();
 -- Preservación columna por columna de TODAS las filas iniciales y control de
 -- incrementos exactos: no pueden aparecer operaciones ni filas adicionales.
 for v in select * from jsonb_each(before_state) loop
  delta:=case v.key when 'compras_gastos' then 60 when 'items_compras_gastos' then 60
   when 'operaciones_compras_gastos' then 60 when 'operaciones_financieras_compras' then 173
   when 'evidencias_financiacion_historica_compras' then 58 when 'financiaciones_compras' then 59
   when 'tramos_pago_compras' then 59 when 'inicios_tramos_tarjeta' then 57
   when 'obligaciones_tarjetas' then 280 when 'cortes_historicos_obligaciones_tarjeta' then 54 else 0 end;
  if not ((after_state->v.key) @> v.value)
   or jsonb_array_length(after_state->v.key)<>jsonb_array_length(v.value)+delta then
   raise exception 'C PARCIAL_O_INCONSISTENTE: preservación %',v.key; end if;
 end loop;
 if ctl.infraestructura is distinct from public.catalogo_lote_compras_historicas_interno() then
  raise exception 'C PARCIAL_O_INCONSISTENTE: infraestructura final'; end if;
 update public.control_lote_compras_historicas set actor_id=actor,antes=before_state,despues=after_state,aplicado_at=clock_timestamp()
  where clave=ctl.clave;
 -- La respuesta se entrega por PostgREST después del cierre de su transacción.
 return jsonb_build_object('estado_lote','IMPORTADO_CORRECTAMENTE','compras_historicas',60,
  'obligaciones_monetarias',280,'cortes_historicos',54,'saldo_pendiente',14259630.21);
end;
$rpc$;

-- Cierra explícitamente TODOS los helpers, aun con default privileges abiertos.
do $acl$
declare f regprocedure;
begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='public' and p.proname in ('catalogo_lote_compras_historicas_interno',
  'datos_lote_compras_historicas_interno','referencias_lote_compras_historicas_interno',
  'snapshot_lote_compras_historicas_interno','validar_referencias_lote_compras_historicas_interno',
  'validar_baseline_lote_compras_historicas_interno','validar_resultado_lote_compras_historicas_interno',
  'proteger_control_lote_compras_historicas_interno','importar_lote_compras_historicas_admin') loop
  execute format('alter function %s owner to postgres',f);
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f);
 end loop;
end;
$acl$;
grant execute on function public.importar_lote_compras_historicas_admin() to authenticated;

-- Sólo metadatos de infraestructura. Ningún dato financiero se escribe al instalar.
do $preflight$
declare f record;
begin
 if current_setting('server_version_num')::integer<170000 then raise exception 'Se requiere PostgreSQL 17'; end if;
 -- Hashes de cuerpos de la 140004 aprobada; no adopta funciones alteradas.
 for f in select * from (values
 ('canonicalizar_evidencia_historica_interno','ff597a9e9042a2fbd686357d63f57197'),
 ('validar_evidencia_compra_interno','3a763ad0a658c1ff64dfe1986910c17b'),
 ('proteger_evidencia_historica_compra','d0269d0dcc6ccc15ca736611e6448b50'),
 ('validar_evidencia_historica_compra','43ce37e59058b76caed19c2c4a013598'),
 ('proteger_compra_documental_historica','bb64df88c02aefa2b3da68489320e9d9'),
 ('validar_compra_historica_integridad','fe876829d573abc8a38066a898d0b172'),
 ('validar_financiacion_compras_integridad','dba67311dda903ce72e2421a5e9434e5'),
 ('confirmar_financiacion_compra_interno','a749232044e96eee9d140cc1d4dc1c91'),
 ('importar_compra_historica_admin','2d26861f856c863de2163d27cb99ed90'),
 ('importar_compra_historica_admin','e5705da4beddc2ee71637625eaf97e36'),
 ('obtener_compra_gasto_admin','1f667e1cdf9958869837c73e87142a02'),
 ('obtener_financiacion_compra_admin','ebf18fcf1ceceedb9af5688e84623438'),
 ('proteger_operacion_documental_historica','b1f4a71a53a03a2a35fb54f49e61d8a9'),
 ('proteger_corte_historico_obligacion_tarjeta','10fefa237551b0a9c3676af247555087')
,
 ('iniciar_operacion_financiera_compras','24f3395e9cd1e4f902cfcc111a2fa4ff'),
 ('finalizar_operacion_financiera_compras','1f5cbf8eb06f5d71c8d3ad4abd262512'),
 ('canonicalizar_tramos_compra_interno','9e778de812d3082724ac1a396825e47d'),
 ('asignar_obligaciones_compra_interno','d84629edb367151d18e579f9c4b29932'),
 ('validar_operacion_corte_historico','980ef51bdaae9dad533e93c7611ef8b8'),
 ('registrar_corte_historico_obligacion_admin','1638e2a688edd49b61a9ac11f5692b1c')
 ) expected(nombre,hash) loop
  if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname=f.nombre and md5(p.prosrc)=f.hash
    and p.proowner='postgres'::regrole and p.prosecdef and p.proconfig=array['search_path=""']) then
   raise exception 'Infraestructura 140004 incompatible: %',f.nombre; end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   where n.nspname='public' and p.proname=f.nombre and a.privilege_type='EXECUTE'
    and (a.grantee in (0,'anon'::regrole,'service_role'::regrole)
     or (a.grantee='authenticated'::regrole and f.nombre not in
      ('importar_compra_historica_admin','registrar_corte_historico_obligacion_admin',
       'obtener_compra_gasto_admin','obtener_financiacion_compra_admin')))) then
   raise exception 'Permisos financieros incompatibles: %',f.nombre; end if;
 end loop;
 -- Huella PG17 de las 16 tablas financieras/de referencia: incluye columnas,
 -- constraints, índices, triggers, RLS y ACL. No contiene datos ni OID.
 if md5(((public.catalogo_lote_compras_historicas_interno()->'tablas')-'control_lote_compras_historicas')::text)
  is distinct from '15dc32406b25c72adc4d3b7092c22861' then
  raise exception 'Estructura/seguridad financiera incompatible con 140004'; end if;
end;
